 * @returns the value of 'property'
 */
getValueOfPropertyAt<T extends StylePropertiesType>(
  lineIndex: number,
  charIndex: number,
  property: T,
): this[T] {
  const charStyle = this._getStyleDeclaration(lineIndex, charIndex);
  return (charStyle[property] ?? this[property]) as this[T];
}

/**
 * @private
 * @param {CanvasRenderingContext2D} ctx Context to render on
 */
_renderTextDecoration(
  ctx: CanvasRenderingContext2D,
  type: 'underline' | 'linethrough' | 'overline',
) {
  if (!this[type] && !this.styleHas(type)) {
    return;
  }
  let topOffset = this._getTopOffset();
  const leftOffset = this._getLeftOffset(),
    path = this.path,
    charSpacing = this._getWidthOfCharSpacing(),
    offsetY = this.offsets[type];

  for (let i = 0, len = this._textLines.length; i < len; i++) {
    const heightOfLine = this.getHeightOfLine(i);
    if (!this[type] && !this.styleHas(type, i)) {
      topOffset += heightOfLine;
      continue;
    }
    const line = this._textLines[i];
    const maxHeight = heightOfLine / this.lineHeight;
    const lineLeftOffset = this._getLineLeftOffset(i);
    let boxStart = 0;
    let boxWidth = 0;
    let lastDecoration = this.getValueOfPropertyAt(i, 0, type);
    let lastFill = this.getValueOfPropertyAt(i, 0, FILL);
    let currentDecoration;
    let currentFill;
    const top = topOffset + maxHeight * (1 - this._fontSizeFraction);
    let size = this.getHeightOfChar(i, 0);
    let dy = this.getValueOfPropertyAt(i, 0, 'deltaY');
    for (let j = 0, jlen = line.length; j < jlen; j++) {
      const charBox = this.__charBounds[i][j] as Required<GraphemeBBox>;
      currentDecoration = this.getValueOfPropertyAt(i, j, type);
      currentFill = this.getValueOfPropertyAt(i, j, FILL);
      const currentSize = this.getHeightOfChar(i, j);
      const currentDy = this.getValueOfPropertyAt(i, j, 'deltaY');
      if (path && currentDecoration && currentFill) {
        ctx.save();
        // bug? verify lastFill is a valid fill here.
        ctx.fillStyle = lastFill as string;
        ctx.translate(charBox.renderLeft, charBox.renderTop);
        ctx.rotate(charBox.angle);
        ctx.fillRect(
          -charBox.kernedWidth / 2,
          offsetY * currentSize + currentDy,
          charBox.kernedWidth,
          this.fontSize / 15,
        );
        ctx.restore();
      } else if (
        (currentDecoration !== lastDecoration ||
          currentFill !== lastFill ||
          currentSize !== size ||
          currentDy !== dy) &&
        boxWidth > 0
      ) {
        let drawStart = leftOffset + lineLeftOffset + boxStart;
        if (this.direction === 'rtl') {
          drawStart = this.width - drawStart - boxWidth;
        }
        if (lastDecoration && lastFill) {
          // bug? verify lastFill is a valid fill here.
          ctx.fillStyle = lastFill as string;
          ctx.fillRect(
            drawStart,
            top + offsetY * size + dy,
            boxWidth,
            this.fontSize / 15,
          );
        }
        boxStart = charBox.left;
        boxWidth = charBox.width;
        lastDecoration = currentDecoration;
        lastFill = currentFill;
        size = currentSize;
        dy = currentDy;
      } else {
        boxWidth += charBox.kernedWidth;
      }
    }
    let drawStart = leftOffset + lineLeftOffset + boxStart;
    if (this.direction === 'rtl') {
      drawStart = this.width - drawStart - boxWidth;
    }
    ctx.fillStyle = currentFill as string;
    currentDecoration &&
      currentFill &&
      ctx.fillRect(
        drawStart,
        top + offsetY * size + dy,
        boxWidth - charSpacing,
        this.fontSize / 15,
      );
    topOffset += heightOfLine;
  }
  // if there is text background color no
  // other shadows should be casted
  this._removeShadow(ctx);
}

/**
 * return font declaration string for canvas context
 * @param {Object} [styleObject] object
 * @returns {String} font declaration formatted for canvas context.
 */
_getFontDeclaration(
  {
    fontFamily = this.fontFamily,
    fontStyle = this.fontStyle,
    fontWeight = this.fontWeight,
    fontSize = this.fontSize,
  }: Partial<
    Pick<
      TextStyleDeclaration,

import { FILL, LEFT, STROKE, reNewline } from '../../constants';
import type { TClassProperties } from '../../typedefs';
import type { FabricText } from './Text';

const fontProperties = [
  'fontSize',
  'fontWeight',
  'fontFamily',
  'fontStyle',
] as const;

export const textDecorationProperties = [
  'underline',
  'overline',
  'linethrough',
] as const;

export const textLayoutProperties: string[] = [
  ...fontProperties,
  'lineHeight',
  'text',
  'charSpacing',
  'textAlign',
  'styles',
  'path',
  'pathStartOffset',
  'pathSide',
  'pathAlign',
];

export const additionalProps = [
  ...textLayoutProperties,
  ...textDecorationProperties,
  'textBackgroundColor',
  'direction',
] as const;

export type StylePropertiesType =
  | 'fill'
  | 'stroke'
  | 'strokeWidth'
  | 'fontSize'
  | 'fontFamily'
  | 'fontWeight'
  | 'fontStyle'
  | 'textBackgroundColor'
  | 'deltaY'
  | 'overline'
  | 'underline'
  | 'linethrough';

export const styleProperties: Readonly<StylePropertiesType[]> = [
  ...fontProperties,
  ...textDecorationProperties,
  STROKE,
  'strokeWidth',
  FILL,
  'deltaY',
  'textBackgroundColor',
] as const;

// @TODO: Many things here are configuration related and shouldn't be on the class nor prototype
// regexes, list of properties that are not suppose to change by instances, magic consts.
// this will be a separated effort
export const textDefaultValues: Partial<TClassProperties<FabricText>> = {
  _reNewline: reNewline,
  _reSpacesAndTabs: /[ \t\r]/g,
  _reSpaceAndTab: /[ \t\r]/,
  _reWords: /\S+/g,
  fontSize: 40,
  fontWeight: 'normal',
  fontFamily: 'Times New Roman',
  underline: false,
  overline: false,
  linethrough: false,
  textAlign: LEFT,
  fontStyle: 'normal',
  lineHeight: 1.16,
  superscript: {
    size: 0.6, // fontSize factor
    baseline: -0.35, // baseline-shift factor (upwards)
  },
  subscript: {
    size: 0.6, // fontSize factor
    baseline: 0.11, // baseline-shift factor (downwards)
  },
  textBackgroundColor: '',
  stroke: null,
  shadow: null,
  path: undefined,
  pathStartOffset: 0,
  pathSide: LEFT,
  pathAlign: 'baseline',
  _fontSizeFraction: 0.222,
  offsets: {
    underline: 0.1,
    linethrough: -0.315,
    overline: -0.88,
  },
  _fontSizeMult: 1.13,
  charSpacing: 0,
  deltaY: 0,
  direction: 'ltr',
  CACHE_FONT_SIZE: 400,
  MIN_TEXT_WIDTH: 2,
};

export const JUSTIFY = 'justify';
export const JUSTIFY_LEFT = 'justify-left';
export const JUSTIFY_RIGHT = 'justify-right';
export const JUSTIFY_CENTER = 'justify-center';

