17	 * @param {Object} thisStyle second style to compare
18	 * @param {boolean} forTextSpans whether to check overline, underline, and line-through properties
19	 * @return {boolean} true if the style changed
20	 */
21	export const hasStyleChanged = (
22	  prevStyle: TextStyleDeclaration,
23	  thisStyle: TextStyleDeclaration,
24	  forTextSpans = false,
25	) =>
26	  prevStyle.fill !== thisStyle.fill ||
27	  prevStyle.stroke !== thisStyle.stroke ||
28	  prevStyle.strokeWidth !== thisStyle.strokeWidth ||
29	  prevStyle.fontSize !== thisStyle.fontSize ||
30	  prevStyle.fontFamily !== thisStyle.fontFamily ||
31	  prevStyle.fontWeight !== thisStyle.fontWeight ||
32	  prevStyle.fontStyle !== thisStyle.fontStyle ||
33	  prevStyle.textBackgroundColor !== thisStyle.textBackgroundColor ||
34	  prevStyle.deltaY !== thisStyle.deltaY ||
35	  (forTextSpans &&
36	    (prevStyle.overline !== thisStyle.overline ||
37	      prevStyle.underline !== thisStyle.underline ||
38	      prevStyle.linethrough !== thisStyle.linethrough));
39	
40	/**
41	 * Returns the array form of a text object's inline styles property with styles grouped in ranges
42	 * rather than per character. This format is less verbose, and is better suited for storage
43	 * so it is used in serialization (not during runtime).
44	 * @param {object} styles per character styles for a text object
45	 * @param {String} text the text string that the styles are applied to
46	 * @return {{start: number, end: number, style: object}[]}
47	 */
48	export const stylesToArray = (
49	  styles: TextStyle,
50	  text: string,
51	): TextStyleArray => {
52	  const textLines = text.split('\n'),
53	    stylesArray = [];
54	  let charIndex = -1,
