    deltaY ? `baseline-shift: ${-deltaY}; ` : '',
    useWhiteSpace ? 'white-space: pre; ' : '',
  ].join('');
}

/**
 * Returns the rendered weight (in px) of the decoration lines for svg-export.
 * Mirrors the weight used while rendering to canvas
 * (`fontSize / 15 * textDecorationThickness`) so a rendered scene and its
 * serialised SVG agree on the weight actually applied.
 * @param {Object} style the object from which to retrieve style properties
 * @return {Number}
 */
getSvgTextDecorationThickness(
  this: TextSVGExportMixin & FabricText,
  style: TextStyleDeclaration,
) {
  const fontSize = style.fontSize ?? this.fontSize;
  const thickness = style.textDecorationThickness ?? this.textDecorationThickness;
  return (fontSize / 15) * thickness;
}

