import { describe, it, expect } from 'vitest';
import { FabricText } from '../../src/shapes/Text/Text';

describe('textDecorationThickness feature', () => {
  it('defaults to 1 and round-trips', () => {
    const t = new FabricText('hello', { underline: true });
    expect(t.textDecorationThickness).toBe(1);
    const obj = t.toObject();
    expect(obj.textDecorationThickness).toBe(1);
    const rebuilt = new FabricText('hello', obj);
    expect(rebuilt.textDecorationThickness).toBe(1);
  });

  it('per-character thickness survives serialization round-trip', async () => {
    const t = new FabricText('abc', {
      underline: true,
      styles: { 0: { 1: { textDecorationThickness: 3 } } },
    });
    const obj = t.toObject();
    const rebuilt = await FabricText.fromObject(obj);
    expect(rebuilt.getValueOfPropertyAt(0, 0, 'textDecorationThickness')).toBe(1);
    expect(rebuilt.getValueOfPropertyAt(0, 1, 'textDecorationThickness')).toBe(3);
    // identical output: same serialized object
    expect(rebuilt.toObject()).toEqual(obj);
  });

  it('reaches underline, overline and linethrough in SVG and scales linearly', () => {
    const base = new FabricText('x', {
      underline: true, overline: true, linethrough: true,
      textDecorationThickness: 1, fontSize: 30,
    });
    const svg1 = base.toSVG();
    const m1 = svg1.match(/text-decoration-thickness="([\d.]+)"/);
    expect(m1).toBeTruthy();
    const v1 = parseFloat(m1![1]);
    expect(v1).toBeCloseTo(30 / 15, 5); // fontSize/15 * 1

    const tripled = new FabricText('x', {
      underline: true, overline: true, linethrough: true,
      textDecorationThickness: 3, fontSize: 30,
    });
    const m3 = tripled.toSVG().match(/text-decoration-thickness="([\d.]+)"/);
    const v3 = parseFloat(m3![1]);
    expect(v3).toBeCloseTo(v1 * 3, 5);
  });

  it('default is indistinguishable in SVG whether set explicitly or not', () => {
    const a = new FabricText('x', { underline: true });
    const b = new FabricText('x', { underline: true, textDecorationThickness: 1 });
    expect(a.toSVG()).toBe(b.toSVG());
  });
});
