import { describe, it, expect, vi } from 'vitest';
import { FabricText } from './Text';

function heights(text: FabricText): number[] {
  const rects: number[] = [];
  const ctx = {
    save(){}, restore(){}, translate(){}, rotate(){}, scale(){},
    beginPath(){}, moveTo(){}, lineTo(){}, closePath(){}, fill(){}, stroke(){},
    fillText(){}, strokeText(){}, measureText(){ return { width: 10 }; },
    fillRect(_x: number,_y: number,_w: number,h: number){ rects.push(h); },
    set fillStyle(_v){}, get fillStyle(){ return ''; },
    set font(_v){}, get font(){ return ''; },
    set globalAlpha(_v){}, set textBaseline(_v){}, set strokeStyle(_v){},
    set lineWidth(_v){}, set lineCap(_v){}, set lineJoin(_v){},
    set direction(_v){}, canvas: {},
  } as unknown as CanvasRenderingContext2D;
  (text as any)._renderTextDecoration(ctx, 'underline');
  return rects;
}

describe('canvas decoration weight', () => {
  it('default weight equals fontSize/15 exactly', () => {
    const t = new FabricText('abc', { underline: true, fontSize: 40 });
    const hs = heights(t);
    expect(hs.length).toBeGreaterThan(0);
    hs.forEach((h) => expect(h).toBe(40 / 15));
  });

  it('object-level thickness scales the drawn weight linearly', () => {
    const t = new FabricText('abc', { underline: true, fontSize: 40, textDecorationThickness: 2.5 });
    heights(t).forEach((h) => expect(h).toBeCloseTo((40 / 15) * 2.5, 9));
  });

  it('per-character thickness varies within a single object', () => {
    const t = new FabricText('ab', {
      underline: true, fontSize: 40,
      styles: { 0: { 1: { textDecorationThickness: 4 } } },
    });
    const hs = heights(t);
    // two separate rects with different weights
    const unique = new Set(hs.map((h) => Math.round(h * 1000)));
    expect(unique.size).toBe(2);
    expect(hs).toContain(40 / 15);
    expect(hs.some((h) => Math.abs(h - (40 / 15) * 4) < 1e-9)).toBe(true);
  });
});
EOF
