it('textDecorationThickness defaults to 1 and survives the object round-trip', async () => {
  const text = new FabricText('abc', {
    underline: true,
    styles: { 0: { 1: { textDecorationThickness: 3 } } },
  });
  expect(text.textDecorationThickness, 'default is 1').toBe(1);
