    object.textDecorationThickness,
    'object level value is serialized',
  ).toBe(1);
  const rebuilt = await FabricText.fromObject(object);
  expect(
    rebuilt.getValueOfPropertyAt(0, 0, 'textDecorationThickness'),
    'default char keeps the object level value',
  ).toBe(1);
  expect(
    rebuilt.getValueOfPropertyAt(0, 1, 'textDecorationThickness'),
    'per char override survives the round-trip',
  ).toBe(3);
  expect(
    rebuilt.toObject(),
    'rebuilt object is identical to the source',
  ).toEqual(object);
});

it('textDecorationThickness is reported in SVG for every decoration line and scales linearly', () => {
  const single = new FabricText('x', {
    underline: true,
    overline: true,
    linethrough: true,
    fontSize: 30,
  });
  const singleThickness = single
    .toSVG()
    .match(/text-decoration-thickness="([\d.]+)"/);
  expect(singleThickness, 'thickness is present when decorated').toBeTruthy();
  const base = parseFloat(singleThickness![1]);
  expect(base, 'default weight is fontSize / 15').toBeCloseTo(30 / 15, 5);

  const tripled = new FabricText('x', {
    underline: true,
    overline: true,
    linethrough: true,
    fontSize: 30,
    textDecorationThickness: 3,
  });
  const tripledThickness = parseFloat(
    tripled.toSVG().match(/text-decoration-thickness="([\d.]+)"/)![1],
  );
  expect(tripledThickness, 'tripling the setting triples the weight').toBeCloseTo(
    base * 3,
    5,
  );
});

